/* Shared visual settings. No authentication or server persistence is implied. */
window.Design=(()=>{
  const KEY='flow-design-v1';
  const widgets={balance:'잔액·핵심 현황',quick:'빠른 실행',stats:'요약 지표',assets:'자산·업무 목록',activity:'최근 활동',promo:'추천 프로그램',referral:'초대·혜택'};
  const defaults={preset:'flow',layout:'sidebar',dashboard:'balanced',font:'noto',scale:100,accent:'#f56524',background:'#f7f8fa',surface:'#ffffff',text:'#20242b',useSector:true,radius:20,density:'comfortable',shadow:false,visible:Object.fromEntries(Object.keys(widgets).map(k=>[k,true]))};
  const presets={flow:{name:'오리지널',note:'밝고 친근한 카드',colors:['#f56524','#f7f8fa','#ffffff'],values:{}},ocean:{name:'오션',note:'정돈된 업무 대시보드',colors:['#2563eb','#eef3fa','#ffffff'],values:{accent:'#2563eb',background:'#eef3fa',layout:'top',dashboard:'operations',radius:12,font:'gothic',useSector:false}},studio:{name:'스튜디오',note:'여유로운 편집 스타일',colors:['#7450c9','#f4f1f9','#ffffff'],values:{accent:'#7450c9',background:'#f4f1f9',layout:'sidebar',dashboard:'focus',radius:28,font:'serif',useSector:false}},night:{name:'미드나이트',note:'차분한 다크 워크스페이스',colors:['#58c6b4','#13191e','#202930'],values:{accent:'#58c6b4',background:'#13191e',surface:'#202930',text:'#f0f4f7',layout:'compact',dashboard:'balanced',radius:16,useSector:false}}};
  const fonts={noto:'"Noto Sans KR", sans-serif',gothic:'"Gothic A1", sans-serif',serif:'"Noto Serif KR", serif',system:'-apple-system, BlinkMacSystemFont, "Apple SD Gothic Neo", sans-serif'};
  const clone=x=>JSON.parse(JSON.stringify(x));
  function normalize(input){const d=clone(defaults),s=input&&typeof input==='object'?input:{};for(const k of ['accent','background','surface','text'])if(/^#[0-9a-f]{6}$/i.test(s[k]))d[k]=s[k];for(const [k,allowed] of Object.entries({preset:Object.keys(presets),layout:['sidebar','top','compact'],dashboard:['balanced','focus','operations'],font:Object.keys(fonts),density:['comfortable','compact']}))if(allowed.includes(s[k]))d[k]=s[k];for(const [k,min,max]of [['radius',0,32],['scale',100,120]])if(typeof s[k]==='number'&&Number.isFinite(s[k]))d[k]=Math.min(max,Math.max(min,s[k]));for(const k of ['useSector','shadow'])if(typeof s[k]==='boolean')d[k]=s[k];for(const k of Object.keys(widgets))if(typeof s.visible?.[k]==='boolean')d.visible[k]=s.visible[k];return d;}
  let saved=clone(defaults);try{saved=normalize(JSON.parse(localStorage.getItem(KEY)))}catch{}
  let draft=clone(saved),previewSettings=null,device='desktop',observer;
  const preview=new URLSearchParams(location.search).has('design-preview');
  const el=s=>document.querySelector(s);
  function rgb(hex){return [1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255)}
  function luminance(hex){return rgb(hex).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4).reduce((a,v,i)=>a+v*[.2126,.7152,.0722][i],0)}
  function contrast(a,b){let x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
  function foreground(bg){return contrast(bg,'#ffffff')>=contrast(bg,'#172029')?'#ffffff':'#172029'}
  function current(){return previewSettings||saved}
  function apply(){const s=current(),root=document.documentElement;let accent=s.useSector?c().accent:s.accent;root.style.setProperty('--accent',accent);root.style.setProperty('--bg',s.background);root.style.setProperty('--surface',s.surface);root.style.setProperty('--ink',s.text);root.style.setProperty('--on-accent',foreground(accent));root.style.setProperty('--muted',`color-mix(in srgb, ${s.text} 66%, ${s.surface})`);root.style.setProperty('--line',`color-mix(in srgb, ${s.text} 13%, ${s.surface})`);root.style.setProperty('--soft',`color-mix(in srgb, ${s.text} 5%, ${s.surface})`);root.style.setProperty('--radius',s.radius+'px');root.style.setProperty('--font-family',fonts[s.font]);root.style.setProperty('--type-scale',s.scale/100);document.body.dataset.layout=s.layout;document.body.dataset.dashboard=s.dashboard;document.body.dataset.density=s.density;document.body.dataset.shadow=String(s.shadow);document.body.classList.toggle('design-preview',preview);}
  function dashboard(){const main=el('#main'),top=main.querySelector('.top-grid'),body=main.querySelector('.body-grid');if(!top||!body)return;const nodes={balance:top.querySelector('.balance'),quick:top.querySelector('.quick'),stats:main.querySelector('.stats'),assets:body.querySelector('.panel'),activity:body.querySelectorAll('.panel')[1],promo:body.querySelector('.promo'),referral:body.querySelector('.referral')};const grid=document.createElement('div');grid.className='dashboard-canvas';const s=current();const order=s.dashboard==='operations'?['stats','assets','activity','balance','quick','promo','referral']:s.dashboard==='focus'?['balance','stats','assets','quick','activity','promo','referral']:Object.keys(widgets);for(const k of order){const node=nodes[k];if(node&&s.visible[k]){node.dataset.widget=k;grid.appendChild(node)}}top.remove();body.remove();nodes.stats?.remove();if(s.visible.stats&&nodes.stats)grid.insertBefore(nodes.stats,grid.children[order.filter(k=>s.visible[k]).indexOf('stats')]||null);main.appendChild(grid);if(!grid.children.length){const p=document.createElement('p');p.className='notice';p.textContent='표시할 대시보드 항목이 없습니다. 디자인 관리에서 항목을 켜주세요.';grid.appendChild(p)}}
  const options=(items,value)=>Object.entries(items).map(([k,v])=>`<option value="${k}" ${String(value)===k?'selected':''}>${v}</option>`).join('');
  function dirty(){return JSON.stringify(draft)!==JSON.stringify(saved)}
  function updateStatus(){const node=el('#design-status');if(node)node.textContent=dirty()?'저장하지 않은 변경사항':'저장된 디자인';const save=el('#save-design');if(save)save.disabled=!dirty();const warning=el('#contrast-note');if(warning){let ratio=contrast(draft.text,draft.surface);warning.textContent=`본문 대비 ${ratio.toFixed(1)}:1${ratio<4.5?' · 글자색과 카드색의 대비를 높여주세요.':' · 읽기 좋은 대비입니다.'}`;warning.classList.toggle('low-contrast',ratio<4.5)}const color=el('[data-setting="accent"]');if(color)color.disabled=draft.useSector;}
  function sendPreview(){const frame=el('#design-preview');if(frame?.contentWindow)frame.contentWindow.postMessage({type:'flow-design-preview',settings:draft,sector:sector},location.origin);updateStatus()}
  function fitPreview(){const frame=el('#design-preview'),stage=el('.preview-stage');if(!frame||!stage)return;const width=device==='mobile'?390:1200,available=stage.clientWidth-24,scale=Math.min(1,available/width);frame.style.width=width+'px';frame.style.height=(device==='mobile'?844:960)+'px';frame.style.transform=`scale(${scale})`;el('.preview-viewport').style.height=(device==='mobile'?844:960)*scale+'px';el('.preview-viewport').style.width=width*scale+'px';}
  function renderAdmin(keepDraft=false){observer?.disconnect();if(!keepDraft)draft=clone(saved);apply();document.title='디자인 관리 | FLOW';el('#breadcrumb').textContent='관리자 / 디자인 스튜디오';el('#desktop-nav').innerHTML=paths.map((p,i)=>`<a href="#${p}">${icon(i)}<span>${c().menus[i]}</span></a>`).join('');el('#mobile-nav').innerHTML='<a href="#home">← 대시보드로 돌아가기</a>';el('#main').innerHTML=`<div class="studio-heading"><div><span class="eyebrow">DESIGN STUDIO</span><h1>내 서비스에 맞는 디자인.</h1><p>색부터 구성까지, 바꾸면서 확인하세요.</p></div><div class="studio-actions"><button class="secondary" data-design-action="undo">변경 취소</button><button class="primary" id="save-design" data-design-action="save">디자인 저장</button></div></div><div class="studio-notice"><span id="design-status" role="status"></span><span>이 브라우저에만 저장됩니다. 실제 관리자 인증·전체 사용자 적용은 미연동입니다.</span></div><div class="studio-grid"><section class="design-controls" aria-label="디자인 설정"><section class="control-section"><h2><span>01</span> 디자인 프리셋</h2><div class="preset-grid">${Object.entries(presets).map(([k,p])=>`<button class="preset ${draft.preset===k?'chosen':''}" data-preset="${k}" aria-pressed="${draft.preset===k}"><span class="preset-art" style="background:${p.colors[1]}"><i style="background:${p.colors[0]}"></i><i style="background:${p.colors[2]}"></i><i style="background:${p.colors[0]}"></i></span><b>${p.name}</b><small>${p.note}</small></button>`).join('')}</div></section><section class="control-section"><h2><span>02</span> 레이아웃 & 구성</h2><label class="control-field">메뉴 배치<select data-setting="layout">${options({sidebar:'사이드바 · 기본',top:'상단 내비게이션',compact:'슬림 사이드바'},draft.layout)}</select></label><label class="control-field">대시보드 구성<select data-setting="dashboard">${options({balanced:'균형형 · 자산과 활동을 함께',focus:'자산 중심형 · 핵심 현황 강조',operations:'업무 중심형 · 목록과 지표 우선'},draft.dashboard)}</select></label><p class="control-hint">모바일에서는 하단 메뉴로 자동 전환됩니다.</p><div class="widget-toggles">${Object.entries(widgets).map(([k,v])=>`<label><span>${v}</span><input type="checkbox" data-widget="${k}" ${draft.visible[k]?'checked':''}></label>`).join('')}</div></section><section class="control-section"><h2><span>03</span> 폰트 & 간격</h2><label class="control-field">글꼴<select data-setting="font">${options({noto:'Noto Sans KR · 모던 고딕',gothic:'Gothic A1 · 또렷한 고딕',serif:'Noto Serif KR · 차분한 명조',system:'시스템 글꼴 · 빠르고 익숙하게'},draft.font)}</select></label><div class="font-sample" style="font-family:${fonts[draft.font].replaceAll('"',"'")}">좋은 흐름의 시작, FLOW.<small>가나다라마바사 0123456789</small></div><label class="control-field">글자 크기<select data-setting="scale">${options({'100':'기본 · 100%','110':'크게 · 110%','120':'더 크게 · 120%'},draft.scale)}</select></label><label class="control-field">화면 밀도<select data-setting="density">${options({comfortable:'여유롭게',compact:'촘촘하게'},draft.density)}</select></label></section><section class="control-section"><h2><span>04</span> 컬러 & 카드</h2><label class="switch-row"><span>업종 기본 강조색 사용</span><input type="checkbox" data-setting="useSector" ${draft.useSector?'checked':''}></label><div class="color-grid">${[['accent','강조색'],['background','배경색'],['surface','카드색'],['text','글자색']].map(([k,label])=>`<label class="color-control"><span>${label}</span><input type="color" aria-label="${label}" data-setting="${k}" value="${draft[k]}"><output data-color-value="${k}">${draft[k].toUpperCase()}</output></label>`).join('')}</div><p id="contrast-note" class="control-hint"></p><label class="control-field">모서리 둥글기 <output id="radius-value">${draft.radius}px</output><input type="range" data-setting="radius" min="0" max="32" value="${draft.radius}"></label><label class="switch-row"><span>카드 그림자</span><input type="checkbox" data-setting="shadow" ${draft.shadow?'checked':''}></label></section><button class="reset-design" data-design-action="reset">기본 디자인으로 되돌리기</button></section><section class="preview-column" aria-label="실시간 디자인 미리보기"><div class="preview-toolbar"><div><b>실시간 미리보기</b><small>저장 전에도 변경 내용을 확인할 수 있어요.</small></div><div class="device-switch"><button data-device="desktop" aria-pressed="${device==='desktop'}">PC</button><button data-device="mobile" aria-pressed="${device==='mobile'}">모바일</button></div></div><div class="preview-sector"><label for="preview-sector">미리볼 업종</label><select id="preview-sector">${options({coin:'코인',logistics:'물류',startup:'창업'},sector)}</select><a href="#home">대시보드 열기 ↗</a></div><div class="preview-stage"><div class="preview-viewport"><iframe id="design-preview" title="대시보드 디자인 미리보기" src="./?design-preview=1#home"></iframe></div></div><p class="preview-note">프리셋 선택 후에도 색상·글꼴·카드 구성을 자유롭게 조정할 수 있습니다.</p></section></div>`;el('#design-preview').addEventListener('load',sendPreview);observer=new ResizeObserver(fitPreview);observer.observe(el('.preview-stage'));fitPreview();updateStatus()}
  document.addEventListener('input',e=>{const input=e.target;if(!input.closest('.design-controls'))return;if(input.dataset.widget)draft.visible[input.dataset.widget]=input.checked;else if(input.dataset.setting){const k=input.dataset.setting;draft[k]=input.type==='checkbox'?input.checked:['radius','scale'].includes(k)?Number(input.value):input.value;if(k==='font')el('.font-sample').style.fontFamily=fonts[draft.font];if(k==='radius')el('#radius-value').textContent=draft.radius+'px';const output=el(`[data-color-value="${k}"]`);if(output)output.textContent=input.value.toUpperCase()}sendPreview()});
  document.addEventListener('change',e=>{if(e.target.id==='preview-sector'){sector=e.target.value;el('#sector').value=sector;sendPreview()}});
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preset){draft=normalize({...defaults,...presets[b.dataset.preset].values,preset:b.dataset.preset});renderAdmin(true)}if(b.dataset.device){device=b.dataset.device;document.querySelectorAll('[data-device]').forEach(n=>n.setAttribute('aria-pressed',n.dataset.device===device));fitPreview()}const action=b.dataset.designAction;if(action==='save'){try{const next=normalize(draft);localStorage.setItem(KEY,JSON.stringify(next));saved=next;draft=clone(next);apply();updateStatus();toast('디자인을 이 브라우저에 저장했습니다.')}catch{toast('저장하지 못했습니다. 브라우저의 저장 공간 설정을 확인해주세요.')}}if(action==='undo'){draft=clone(saved);renderAdmin(true)}if(action==='reset'){draft=clone(defaults);renderAdmin(true)}});
  window.addEventListener('message',e=>{if(!preview||e.origin!==location.origin||e.source!==parent||e.data?.type!=='flow-design-preview')return;previewSettings=normalize(e.data.settings);if(SECTORS[e.data.sector])sector=e.data.sector;render()});
  window.addEventListener('storage',e=>{if(e.key===KEY){try{saved=normalize(JSON.parse(e.newValue));if(location.hash!=='#admin')render()}catch{}}});
  window.addEventListener('hashchange',()=>{if(location.hash!=='#admin')observer?.disconnect()});
  return {apply,dashboard,renderAdmin};
})();
